package com.yeyamo_mobile.api.notification_service.infrastructure.messaging;
import static org.mockito.Mockito.*;import java.util.*;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.notification_service.application.*;
class NotificationEventConsumerTest{@Test void persistentReceiptMakesConsumptionIdempotent()throws Exception{UUID id=UUID.randomUUID();var policy=mock(EventNotificationPolicy.class);var service=mock(NotificationApplicationService.class);var receipts=mock(ProcessedEventRepository.class);var mapper=new ObjectMapper();String raw="{\"eventId\":\""+id+"\",\"eventType\":\"user.created\",\"eventVersion\":1,\"payload\":{\"userId\":\"1\"}}";var intent=new NotificationIntent(id,"user.created","1",null,Map.of(),"{}");when(policy.map(any())).thenReturn(List.of(intent));when(receipts.existsById(id)).thenReturn(false,true);var consumer=new NotificationEventConsumer(mapper,policy,service,receipts);consumer.consume(raw);consumer.consume(raw);verify(service,times(1)).create(intent);verify(receipts,times(1)).save(any());}}
